def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

    # Load GSL functions
    gsl_integration_cquad = gsl.gsl_integration_cquad
    gsl_function_fdf = ctypes.CFUNCTYPE(None, ctypes.c_void_p, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double))
    gsl_set_error_handler_t = ctypes.CFUNCTYPE(None, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p)

    # Convert Python function to GSL function
    gsl_func = GSLFunction(func)

    # Set workspace size and allocate workspace
    w = CQuadWorkspace(workspace_size)

    # Perform integration
    result, error = gsl_integration_cquad(gsl_function_fdf(gsl_func), a, b, epsabs, epsrel, w.size, w.ptr)

    return (result, error, w.num_evals)

