def get_chebyshev_derivative(coeffs, a, b, order):
    # Load the dynamic libraries in the correct order
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the Chebyshev series class and its methods
    class GslChebSeries(object):
        def __init__(self, coeffs, a, b, order):
            self.coeffs = coeffs
            self.a = a
            self.b = b
            self.order = order

        def derivative(self):
            # Call the gsl_cheb_calc_deriv function from GSL
            deriv = gsl.gsl_cheb_calc_deriv(ctypes.c_double(self.a), ctypes.c_double(self.b), ctypes.c_int(self.order))

            # Handle any errors returned by the C function
            if deriv == 0:
                return None

            # Compute the derivative of the Chebyshev series and return the result
            deriv_coeffs = [deriv[i] for i in range(self.order + 1)]
            return deriv_coeffs

    # Create an instance of the GslChebSeries class with the given coefficients, a, b, and order
    cheb_series = GslChebSeries(coeffs, a, b, order)

    # Compute the derivative of the Chebyshev series and return the result as JSON
    deriv_coeffs = cheb_series.derivative()
    if deriv_coeffs is None:
        return json.dumps({"Error": "Invalid input"})
    else:
        return json.dumps({"Candidate_solution": str(deriv_coeffs)})

