def numpy_to_gsl_matrix(np_array: np.ndarray) -> GSLMatrix:
    matrix = GSLMatrix(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            matrix.matrix[i][j] = float(np_array[i, j])
    return matrix

def gsl_matrix_to_numpy(gsl_matrix: GSLMatrix) -> np.ndarray:
    array = np.empty((gsl_matrix.rows, gsl_matrix.cols), dtype=float)
    for i in range(gsl_matrix.rows):
        for j in range(gsl_matrix.cols):
            array[i, j] = float(gsl_matrix.matrix[i][j])
    return array

