def iqsort(data):
    # Sort the data using the IQ sort algorithm
    n = len(data)
    for i in range(n):
        for j in range(i+1, n):
            if data[j] < data[i]:
                tmp = data[i]
                data[i] = data[j]
                data[j] = tmp
    return data

