@ctypes.CFUNCTYPE(ctypes.c_double, ctypes.POINTER(ctypes.c_double))
def median(data):
    # Compute the median using the IQ sort algorithm
    n = len(data)
    sorted_data = iqsort(data)
    if n % 2 == 0:
        return (sorted_data[n//2] + sorted_data[(n//2)-1]) / 2
    else:
        return sorted_data[n//2]

