    sorted_data = iqsort(data)
    if q == 0.25:
        return sorted_data[n//4]
    elif q == 0.50:
        return (sorted_data[(n//4)] + sorted_data[(n//4)-1]) / 2
    elif q == 0.75:
        return sorted_data[(3*n)//4]

