    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl_sf_bessel_Y1 = gsl.gsl_sf_bessel_Y1
    gsl_sf_bessel_Y1.argtypes = [ctypes.c_double]
    gsl_sf_bessel_Y1.restype = ctypes.c_double
    return gsl_sf_bessel_Y1(x)

