    status = gsl.gsl_bspline_wlssolve(x_vector, y_vector, w_vector, workspace)

    if status != 0:
        raise ValueError("GSL error: " + str(status))

    # Extract the coefficients and chi-squared value from the workspace object
    coefficients = []
    for i in range(workspace.length):
        coefficients.append(workspace.data[i])

