import numpy as np

# Define the required classes and functions
gsl_matrix = ctypes.POINTER(ctypes.c_double * 9)
gsl_vector = ctypes.POINTER(ctypes.c_double * 9)

def matrix_to_gsl(matrix):
    # Convert a Python list representing a matrix to a GSL matrix
    rows, cols = len(matrix), len(matrix[0])
    gsl_matrix_obj = (ctypes.c_double * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            gsl_matrix_obj[i + rows * j] = matrix[i][j]
    return gsl_matrix(gsl_matrix_obj)

def vector_to_gsl(vector):
    # Convert a Python list representing a vector to a GSL vector
    size = len(vector)
    gsl_vector_obj = (ctypes.c_double * size)()
    for i in range(size):
        gsl_vector_obj[i] = vector[i]
    return gsl_vector(gsl_vector_obj)

def gsl_matrix_to_list(matrix):
    # Convert a GSL matrix to a Python list representing a matrix
    rows, cols = matrix.contents.size1, matrix.contents.size2
    result = []
    for i in range(rows):
        result.append([])
        for j in range(cols):
            result[i].append(matrix.contents.data[i + rows * j])
    return result

def gsl_vector_to_list(vector):
    # Convert a GSL vector to a Python list representing a vector
    size = vector.contents.size
    result = [0] * size
    for i in range(size):
        result[i] = vector.contents.data[i]
    return result

def ql_decomposition_and_unpack(A, tau):
    # Perform the QL decomposition of a given matrix and unpack it into matrices Q and L
    gsl_matrix_A = matrix_to_gsl(A)
    gsl_vector_tau = vector_to_gsl(tau)
    Q = ctypes.POINTER(ctypes.c_double * 9)()
    L = ctypes.POINTER(ctypes.c_double * 9)()
    status = gsl.QLDecomp(gsl_matrix_A, gsl_vector_tau, Q, L)
    if status == 0:
        return {"Q": gsl_matrix_to_list(Q), "L": gsl_matrix_to_list(L)}
    else:
        return {}

